mapper.select:
SELECT p.*
FROM payment_order p
JOIN idempotency_request i ON i.business_no=p.payment_no
WHERE i.actor_type='USER'
  AND i.actor_id=#{userId}
  AND i.operation='SUBMIT_PAYMENT'
  AND i.idempotency_key=#{idempotencyKey}
  AND p.user_id=#{userId}
  AND p.order_no=#{orderNo}

mapper.update:
UPDATE payment_order
SET close_intent='YES',version=version+1
WHERE payment_no=#{paymentNo}

UPDATE process_task
SET step='QUERY',state='READY',next_retry_at=UTC_TIMESTAMP(3),lease_until=NULL,claim_version=claim_version+1,version=version+1
WHERE task_no=#{taskNo}
  AND state='RUNNING'
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
  AND lease_until>UTC_TIMESTAMP(3)

mapper.select:
SELECT *
FROM process_task
WHERE task_no=#{taskNo}
  AND state='RUNNING'
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
  AND lease_until>UTC_TIMESTAMP(3) FOR UPDATE

mapper.update:
UPDATE process_task
SET state=#{state},step=#{step},last_error=#{lastError},manual_review_at=IF(#{state}='MANUAL_REVIEW',UTC_TIMESTAMP(3),manual_review_at),next_retry_at=DATE_ADD(UTC_TIMESTAMP(3),INTERVAL 3 SECOND),lease_until=NULL,version=version+1
WHERE task_no=#{taskNo}
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
  AND lease_until>UTC_TIMESTAMP(3)
  AND state='RUNNING'

UPDATE channel_notification
SET process_status='QUARANTINED',reason='终态证据矛盾，人工核验',version=version+1
WHERE notification_no=#{notificationNo}

UPDATE outbox_event
SET status=#{status},published_at=IF(#{status}='SENT',UTC_TIMESTAMP(3),NULL),lease_until=NULL,next_retry_at=DATE_ADD(UTC_TIMESTAMP(3),INTERVAL 5 SECOND),last_error=#{lastError},version=version+1
WHERE event_id=#{eventId}
  AND claim_version=#{claimVersion}
  AND status='RUNNING'

mapper.select:
SELECT *
FROM payment_ledger
ORDER BY id DESC
LIMIT #{size}
OFFSET #{offset}
